clc; clear; close all;
%%%%%%%%%%%%%%%%%%%%% Constant Pararmeters %%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%% Vehicle
m  = 500;          % kg
L  = 4.0;          % m
D  = 0.40;         % m
Area_X  = pi*D^2/4;     % m^2
Area_Y = D*L;           % m^2

%% Inertia
Ix = 250;          % kg m^2
Iy = 800;          % kg m^2
Iz = 800;          % kg m^2

I = diag([Ix Iy Iz]);

%% Propulsion
T = 28000;         % N

%% TVC
delta_max = deg2rad(12);
tau_TVC   = 0.05; % sec

%% CG / thrust location
xCG = 2.0;         % m from nose
rT  = [-1.8; 0; 0]; % m, relative to CG
l1 = 2.2;%m
l2 = 1.8;%m

%% Environment
g   = 9.80665;     % m/s^2
rho = 1.225;       % kg/m^3

%%Airfoil Characteristics
CL_Alpha = 2*pi;%Assuming Thin Airfoil
S = 0.001;%m^2

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%% Simulation %%%%%%%%%%%%%%%%%%%%%%%%%%%

%Taking the No of Iteration as Input - Iteration/100 = Time of Simulation
N = input("Enter the Number of Iteration: ");
K = input("Enter the Navigation Constant (Generally 3-5): ");

% Initializing the Target Position
rt = NaN(3,N+1);

% Initializing the Missile's Position
rm = NaN(3,N+1);

% Target Trajectory
rt(:,1) = [30000; 25000; 15000];%m --- Initial Position
Vt = [200;-220;223];
%Vt = rt(:,1)/500;
at = [25; 30; 35];  %m/s^2

%Distance Between the Missile and Target
R = NaN(3,N+1);
Time = NaN(1,N+1);
Ang_Acc_Mag = NaN(1,N);
%Ang_Acc_Mag(1,1) = 0;%To make the Dimension of this vector equal to others for plotting

%%Assuming missile has reached this position and Velocity
r0 = rt(:,1)/vecnorm(rt(:,1));
rm(:,1) = [0; 0; 0];
Vm = 1*r0;%m/s - Missile
Acc_max = 20*g;%Because we have to take max lateral Acceleration

%%Initial Orientation of the Missile
Angle = NaN(3,N+1);
Angle(:,1) = [0;0;0];
Quat = Angle2quat(Angle(:,1));
p = 0; q = 0; r = 0;%Angular rates in body frame

dt = 0.01;
Time(1) = 0;
fprintf("Initial Distance between the Target and Missile is: %.2f\n",vecnorm(rm(:,1) - rt(:,1))); %[output:6eb51885]

%PID Gains for Angular Acceleration
Kp = 10;
Ki = 3.32;
Kd = 10;
ANGLE = zeros(1,N+1);
Integral = 0;

for i = 1:N

    V_rel = Vt - Vm;
    Vm_mag = vecnorm(Vm);
    Vm_hat = Vm/Vm_mag;
    R(:,i) = rt(:,i) - rm(:,i);
    Omega_LOS = cross(R(:,i),V_rel)/norm(R(:,i))^2;

    RB = Inertial2Body(R(:,i),Quat);
    
    ANGLE(1,i+1) = acos(dot(RB,[1;0;0])/vecnorm(RB));
    %Latex Command
    Acc_cmd = K*Vm_mag*cross(Omega_LOS,Vm_hat);
    Acc_mag = vecnorm(Acc_cmd);

    if Acc_mag > Acc_max
        Acc_cmd = Acc_cmd * Acc_max/Acc_mag;
    end
    Body_Acc = Inertial2Body(Acc_cmd,Quat);%Converting the latex into the Body frame
    Body_Vel = Inertial2Body(Vm,Quat);

    %Angular Acceleration Required
    %Taking theta_dot and theta as a state matrix element and theta_dot_dot
    %as Control Input then the A and B matrix will be-
    %State vector - [Theta_dot; Theta], Control_Input - [Theta_Dot_Dot]
    A_LQR = [0 0;
         1 0];
    B_LQR = [1;
        dt];
    Q_LQR = [0.001 0;
             0 0.0015];
    R_LQR = 0.0025;
    %Solving Algebraic Riccati Equation
    [P_LQR, ~, K_LQR] = care(A_LQR,B_LQR,Q_LQR,R_LQR);
    Derivative = (ANGLE(1,i+1) - ANGLE(1,i))/dt;
    X = [Derivative;
         ANGLE(1,i+1)];
    Ang_Acc_Mag(1,i) = -K_LQR*X;

    %Integral = Integral + ANGLE(1,i+1);
    %Derivative = (ANGLE(1,i+1) - ANGLE(1,i))/dt;
    %Ang_Acc_Mag = Kp*ANGLE(1,i+1) + Ki*Integral + Kd*Derivative;

    Ang_Acc_Dir = cross([1,0,0]',RB)/vecnorm(cross([1,0,0]',RB));

    M_req = -Iy*Ang_Acc_Mag(1,i)*Ang_Acc_Dir;

    Ty = (m*Body_Acc(2,1)*l1 - M_req(3,1))/L;
    Tz = (m*Body_Acc(3,1)*l1 - M_req(2,1))/L;

    %Scaling the Ty and Tz in the range
    if (sqrt(Ty^2 + Tz^2) > T*sind(8))
        Ty = (Ty/sqrt(Ty^2 + Tz^2))*T*sind(8);
        Tz = (Tz/sqrt(Ty^2 + Tz^2))*T*sind(8);
    end
    Tx = sqrt(T^2 - Ty^2 - Tz^2);
    Cy = (m*Body_Acc(2,1)*l2 + M_req(3,1))/L;
    Cz = (m*Body_Acc(3,1)*l2 + M_req(2,1))/L;

    q_inf = 0.5*rho*Vm_mag^2;

    Alpha0_y = atan2(Body_Vel(2,1),Body_Vel(1,1));
    Ly = 2*q_inf*S*CL_Alpha*Alpha0_y;

    Cx0_y = Ly*sin(Alpha0_y);
    Cy0 = -Ly*cos(Alpha0_y);

    Alpha_Need_y = 0.5*((Cy - Cy0)/(q_inf*S*CL_Alpha));

    %%Same for z axis
    Alpha0_z = atan2(Body_Vel(3,1),Body_Vel(1,1));
    Lz = 2*q_inf*S*CL_Alpha*Alpha0_z;

    Cx0_z = Lz*sin(Alpha0_z);
    Cz0 = -Lz*cos(Alpha0_z);

    Alpha_Need_z = 0.5*((Cz - Cz0)/(q_inf*S*CL_Alpha));

    AlphaY = asin(Tx/sqrt(Tx^2 + Ty^2));
    DeltaZ = atan2(Tz,T);%TVC Deflection direction

    % Apply TVC actuator limits 
    DeltaZ = max(-delta_max, min(delta_max, DeltaZ));
    
    %Thrust Force
    F_TVC = T*[sin(DeltaZ)*sin(AlphaY);
               sin(DeltaZ)*cos(AlphaY);
               cos(DeltaZ)];
    %Canard Force
    C = [Ly*sin(Alpha0_y + Alpha_Need_y) + Lz*sin(Alpha0_z + Alpha_Need_z);
         Cy;
         Cz];
    %Drag Force
    CD_x = 0.1;%Ogive Nose Cone
    CD_Y_Z = 0.9;%Body - Cylinder
    Drag = [0.5*rho*(Vm(1,1)^2)*Area_X*CD_x;
            0.5*rho*(Vm(2,1)^2)*Area_Y*CD_Y_Z;
            0.5*rho*(Vm(3,1)^2)*Area_Y*CD_Y_Z];
    %Gravity Force
    g_Body = Inertial2Body([0;0;-9.81],Quat);
    %Assuming No Drag because I don't know the Cd value for missile in
    %x,y,z direction
    F_Total = F_TVC + C + m*g_Body - Drag;


    %Applying Translational Dynamics 
    U_dot = (F_Total(1)/m) - q*Body_Vel(3) + r*Body_Vel(2);
    V_dot = (F_Total(2)/m) - r*Body_Vel(1) + p*Body_Vel(3);
    W_dot = (F_Total(3)/m) - p*Body_Vel(2) + q*Body_Vel(1);

    Body_Vel = Body_Vel + [U_dot; V_dot; W_dot]*dt;

    %Applying Rotational Dynamics
    Moment = M_req;

    p_dot = (Moment(1) - (Iz - Iy)*q*r)/Ix;
    q_dot = (Moment(2) - (Ix - Iz)*r*p)/Iy;
    r_dot = (Moment(3) - (Iy - Ix)*p*q)/Iz;

    p = p + p_dot*dt;
    q = q + q_dot*dt;
    r = r + r_dot*dt;

    %Attitude Update
    Omega = [0 -p -q -r;
             p  0  r -q;
             q  -r 0  p;
             r  q  -p  0];
    
    Quat_dot = (0.5)*Omega*Quat;
    Quat = Quat + Quat_dot*dt;
    Quat = Quat/vecnorm(Quat);
    Angle(:,i+1) = quat2Angle(Quat);

    % Calculate missile's velocity components
    Vm = Body2Inertial(Body_Vel,Quat);     

    %Updating missile's position
    rm(:,i+1) = rm(:,i) + Vm*dt + Acc_cmd*(dt^2/2);

    %Updating Target position
    rt(:,i+1) = rt(:,i) + Vt*dt + 0.5*at*dt^2;
    
    %Updating Target Velocity
    Vt = Vt + at*dt;

    Time(i+1) = Time(i) + dt;
    R(:,i+1) = rt(:,i+1) - rm(:,i+1);
    
    if (norm(R(:,i+1)) < 50) 
        break;
    end

end

if (min(vecnorm(R)) > 50) %[output:group:618d6bfc]
    fprintf("The Target accelerated and got out of reach!\n"); %[output:7e34f693]
end %[output:group:618d6bfc]

if (min(vecnorm(R)) <= 50)
   fprintf("Mission Succesfull! Target Eliminated\n");
end

%Plotting the Target Trajectory

plot3(rt(1,:),rt(2,:),rt(3,:),marker = "o", Color = "r"); %[output:033f425f]
title("Target's Trajectory") %[output:033f425f]
xlabel("X Coordinate"); %[output:033f425f]
ylabel("Y Coordinate"); %[output:033f425f]
zlabel("Z Coordinate"); %[output:033f425f]
hold on; %[output:033f425f]
grid on; %[output:033f425f]

plot3(rm(1,:),rm(2,:),rm(3,:),marker = "*", Color = "g"); %[output:033f425f]
title("Target and Missile's Trajectory") %[output:033f425f]
xlabel("X Coordinate"); %[output:033f425f]
ylabel("Y Coordinate"); %[output:033f425f]
zlabel("Z Coordinate"); %[output:033f425f]

figure; %[output:9717b76b]
plot(Time,vecnorm(R, 2, 1).',marker = "+", Color = "b"); %[output:9717b76b]
title("Reletive distance between the Missile and Interceptor!"); %[output:9717b76b]
xlabel("Time in seconds"); %[output:9717b76b]
ylabel("Distance b/w the Target and Missile"); %[output:9717b76b]
grid on; %[output:9717b76b]

plot (Time, (180/pi)*Angle) %[output:670d7237]
title("Orientation of the Missile with Time"); %[output:670d7237]
xlabel("Time in seconds"); %[output:670d7237]
ylabel("Orientation"); %[output:670d7237]
legend("Phi","Theta","Psi"); %[output:670d7237]
grid on; %[output:670d7237]

plot(Time, (180/pi)*ANGLE,color="g"); %[output:08c19251]
title("Angle b/w Missile and LOS with Time"); %[output:08c19251]
xlabel("Time in seconds"); %[output:08c19251]
ylabel("LOS Angle"); %[output:08c19251]
grid on; %[output:08c19251]
[minimum,idx] = min(vecnorm(R));

plot(Time(1:N),Ang_Acc_Mag) %[output:1626a409]
title("Required Angular Acceleration Magnitude with Time"); %[output:1626a409]
xlabel("Time in seconds"); %[output:1626a409]
ylabel("Angular Acceleration"); %[output:1626a409]
grid on; %[output:1626a409]

fprintf("Time taken to reach closest distance of %.2f m to the Target is: %.2f seconds\n",minimum,Time(idx)); %[output:5f0d7b8a]

fprintf("Final Distance between the Target and Missile is: %.2f\n",norm(R(:,i))); %[output:99f55e53]

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%% Required Functions %%%%%%%%%%%%%%%%%%%%%%%%%%%%

function Angle = quat2Angle(q)
    qn = norm(q);
    q0 = q(1)/qn; q1 = q(2)/qn; q2 = q(3)/qn; q3 = q(4)/qn;
    
    phi   = atan2(2 * (q0 * q1 + q2 * q3), q0 * q0 + q3 * q3 - q1 * q1 - q2 * q2);
    theta  = asin (2 * (q0 * q2 - q1 * q3));
    shi    = atan2(2 * (q0 * q3 + q1 * q2), q0 * q0 + q1 * q1 - q2 * q2 - q3 * q3);
    
    Angle = [phi; theta; shi];
end

function q = Angle2quat(Angle)
    phi = Angle(1); theta = Angle(2); shi = Angle(3);

    cphi = cos(phi/2);   sphi = sin(phi/2);
    cth  = cos(theta/2); sth  = sin(theta/2);
    cshi = cos(shi/2);   sshi = sin(shi/2);
    
    q1 = cphi*cth*cshi + sphi*sth*sshi;   % q0 
    q2 = sphi*cth*cshi - cphi*sth*sshi;   % q1
    q3 = cphi*sth*cshi + sphi*cth*sshi;   % q2
    q4 = cphi*cth*sshi - sphi*sth*cshi;   % q3
    
    q = [q1; q2; q3; q4];
    q = q / norm(q);   % unit magnitude

end

function V_B = Inertial2Body(V_I,Quat)
    Angle = quat2Angle(Quat);
    phi = Angle(1);
    theta = Angle(2);
    psi = Angle(3);

    C_B_N = [cos(theta)*cos(psi), cos(theta)*sin(psi), -sin(theta);
    
             sin(phi)*sin(theta)*cos(psi) - cos(phi)*sin(psi), ...
             sin(phi)*sin(theta)*sin(psi) + cos(phi)*cos(psi), ...
             sin(phi)*cos(theta);
    
             cos(phi)*sin(theta)*cos(psi) + sin(phi)*sin(psi), ...
             cos(phi)*sin(theta)*sin(psi) - sin(phi)*cos(psi), ...
             cos(phi)*cos(theta)];
    
    V_B = C_B_N*V_I;

end

function V_I = Body2Inertial(V_B,Quat)
    Angle = quat2Angle(Quat);
    phi = Angle(1);
    theta = Angle(2);
    psi = Angle(3);

    C_N_B = [cos(theta)*cos(psi), ...
             sin(phi)*sin(theta)*cos(psi) - cos(phi)*sin(psi), ...
             cos(phi)*sin(theta)*cos(psi) + sin(phi)*sin(psi);
    
             cos(theta)*sin(psi), ...
             sin(phi)*sin(theta)*sin(psi) + cos(phi)*cos(psi), ...
             cos(phi)*sin(theta)*sin(psi) - sin(phi)*cos(psi);
    
             -sin(theta), ...
             sin(phi)*cos(theta), ...
             cos(phi)*cos(theta)];
    
    V_I = C_N_B*V_B;

end

